// Package ping serves a contract generated by an older protoc-gen-go.
package ping

import (
	"context"

	"example.com/svc/gen/oldv1"
	"example.com/svc/internal/apierr"
)

type Pinger struct{}

func (Pinger) Ping(ctx context.Context, req *oldv1.PingRequest) (*oldv1.PingResponse, error) {
	if req == nil {
		return nil, apierr.NotFound("PING_FAILED", "declared")
	}
	return nil, apierr.NotFound("PONG", "undeclared") // want `the error reason PONG, which /example.old.v1.PingService/Ping does not declare`
}
